  INSERT INTO policy_parameters (policy_version_id, param_key, value)
  SELECT v_id, k, v FROM (
  SELECT 'bureau.band_min.approve', to_jsonb(score_band_min) FROM rate_grid WHERE band_label = 'APPROVE' AND vehicle_category = 'CAR' AND policy_version = '2026.08' AND is_active
  UNION ALL SELECT 'bureau.band_min.maybe', to_jsonb(score_band_min) FROM rate_grid WHERE band_label = 'MAYBE' AND vehicle_category = 'CAR' AND policy_version = '2026.08' AND is_active
  UNION ALL SELECT 'pricing.base_rate.approve', to_jsonb(rate_pct) FROM rate_grid WHERE band_label = 'APPROVE' AND vehicle_category = 'CAR' AND policy_version = '2026.08' AND is_active
  UNION ALL SELECT 'pricing.base_rate.maybe', to_jsonb(rate_pct) FROM rate_grid WHERE band_label = 'MAYBE' AND vehicle_category = 'CAR' AND policy_version = '2026.08' AND is_active
  UNION ALL SELECT 'caps.max_ltv_pct.approve', to_jsonb(max_ltv_pct) FROM rate_grid WHERE band_label = 'APPROVE' AND vehicle_category = 'CAR' AND policy_version = '2026.08' AND is_active
  UNION ALL SELECT 'caps.max_ltv_pct.maybe', to_jsonb(max_ltv_pct) FROM rate_grid WHERE band_label = 'MAYBE' AND vehicle_category = 'CAR' AND policy_version = '2026.08' AND is_active
  UNION ALL SELECT 'caps.max_foir_pct.approve', to_jsonb(max_foir_pct) FROM rate_grid WHERE band_label = 'APPROVE' AND vehicle_category = 'CAR' AND policy_version = '2026.08' AND is_active
  UNION ALL SELECT 'caps.max_foir_pct.maybe', to_jsonb(max_foir_pct) FROM rate_grid WHERE band_label = 'MAYBE' AND vehicle_category = 'CAR' AND policy_version = '2026.08' AND is_active
  UNION ALL SELECT 'caps.max_tenure_months.approve', to_jsonb(max_tenure_months) FROM rate_grid WHERE band_label = 'APPROVE' AND vehicle_category = 'CAR' AND policy_version = '2026.08' AND is_active
  UNION ALL SELECT 'caps.max_tenure_months.maybe', to_jsonb(max_tenure_months) FROM rate_grid WHERE band_label = 'MAYBE' AND vehicle_category = 'CAR' AND policy_version = '2026.08' AND is_active
  UNION ALL SELECT 'pricing.loading.cat_' || lower(category_code), to_jsonb(rate_loading_pct) FROM employer_category_pricing WHERE policy_version = '2026.08'
  UNION ALL SELECT 'caps.max_ltv_pct.cat_' || lower(category_code), to_jsonb(max_ltv_pct) FROM employer_category_pricing WHERE policy_version = '2026.08'
  UNION ALL SELECT 'caps.max_tenure_months.cat_' || lower(category_code), to_jsonb(max_tenure_months) FROM employer_category_pricing WHERE policy_version = '2026.08'
  UNION ALL SELECT 'charges.processing_fee.cat_' || lower(category_code), to_jsonb(processing_fee_inr) FROM employer_category_pricing WHERE policy_version = '2026.08'
  ) AS src(k, v);

  GET DIAGNOSTICS v_count = ROW_COUNT;
  IF v_count <> 22 THEN
    RAISE EXCEPTION 'expected 22 baseline parameters, found % — check rate_grid and employer_category_pricing (migration 011)', v_count;
  END IF;

  UPDATE policy_versions
  SET status = 'ACTIVE', effective_from = '2026-08-01 00:00:00+05:30'
  WHERE id = v_id;
END
$seed$;

